#include <iostream>

int main() {
    // Standard counter-controlled loop counting from 1 to 5
    for (unsigned int counter = 1; counter <= 5; ++counter) {
        std::cout << counter << " ";
    }
    std::cout << "\n";

    // Summing even integers from 2 to 10
    unsigned int total = 0;
    for (unsigned int number = 2; number <= 10; number += 2) {
        total += number;
    }
    std::cout << "Sum: " << total << "\n";

    return 0;
}

#include <iostream>

int main() {
    // Pattern 1: Arithmetic step progression (2, 5, 8, 11, 14, 17)
    std::cout << "Progression: ";
    for (int j = 2; j <= 17; j += 3) {
        std::cout << j << " ";
    }
    std::cout << "\n";

    // Pattern 2: Decrementing loop (44, 33, 22, 11, 0)
    std::cout << "Countdown: ";
    for (int j = 44; j >= 0; j -= 11) {
        std::cout << j << " ";
    }
    std::cout << "\n";

    // Pattern 3: Dual variables synchronized via comma operator
    std::cout << "Converging: ";
    for (int left = 1, right = 5; left <= right; ++left, --right) {
        std::cout << "[" << left << "," << right << "] ";
    }
    std::cout << "\n";

    return 0;
}
